// ------------------------------------------------------------------ helpers
static constexpr hf TWO_PI_H   = HC(6.283185307179586);
static constexpr hf PI_H       = HC(3.141592653589793);
static constexpr hf AA_SIGMA   = HC(0.35);   // LEDs; widens narrow waveform features so they don't alias
static constexpr int NOISE_TP  = 4096;       // noise lattice period along time
static constexpr uint8_t BLEND_NORMAL = 0, BLEND_ADD = 1, BLEND_SCREEN = 2;
static constexpr int DIR_FWD = 1, DIR_BWD = 2;

// waveform components: centre, sigma (fractions of width), amplitude
struct Comp { hf mu, sigma, amp; };
static const Comp SHAPE_ECG[]    = { {HC(0.10), HC(0.035), HC(0.15)}, {HC(0.30), HC(0.02), HC(-0.15)}, {HC(0.36), HC(0.025), HC(1.0)}, {HC(0.43), HC(0.03), HC(-0.5)}, {HC(0.72), HC(0.07), HC(0.32)} };
static const Comp SHAPE_LUBDUB[] = { {HC(0.30), HC(0.09), HC(1.0)}, {HC(0.68), HC(0.08), HC(0.6)} };
static const Comp SHAPE_BUMP[]   = { {HC(0.50), HC(0.16), HC(1.0)} };

static const hf GX[8] = { HC(1), HC(-1), HC(0), HC(0), HC(0.7071067811865476), HC(-0.7071067811865476), HC(0.7071067811865476), HC(-0.7071067811865476) };
static const hf GY[8] = { HC(0), HC(0), HC(1), HC(-1), HC(0.7071067811865476), HC(0.7071067811865476), HC(-0.7071067811865476), HC(-0.7071067811865476) };

static inline hf clamp01(hf x) { return x < 0 ? HC(0) : (x > 1 ? HC(1) : x); }
static inline hf maxh(hf a, hf b) { return a > b ? a : b; }
static inline hf minh(hf a, hf b) { return a < b ? a : b; }
static inline hf smoothstep(hf e0, hf e1, hf x) {
  if (e0 == e1) return x < e0 ? HC(0) : HC(1);
  hf t = clamp01((x - e0) / (e1 - e0));
  return t * t * (3 - 2 * t);
}
// 1 before a, 0 after b, smooth in between
static inline hf fadeOut(hf a, hf b, hf x) {
  if (b <= a) return x < a ? HC(1) : HC(0);
  return 1 - smoothstep(a, b, x);
}
static inline hf fmodp(hf a, hf m) { hf r = std::fmod(a, m); return r < 0 ? r + m : r; }
static inline int imodp(int a, int m) { int r = a % m; return r < 0 ? r + m : r; }
static inline int iround(hf v) { return (int)std::floor(v + HC(0.5)); }
static inline uint32_t hash32(uint32_t x) {
  x ^= x >> 16; x *= 0x7feb352dU;
  x ^= x >> 15; x *= 0x846ca68bU;
  x ^= x >> 16;
  return x;
}
static inline uint32_t hash3(uint32_t a, uint32_t b, uint32_t c) { return hash32(a * 0x8da6b343U ^ b * 0xd8163841U ^ c * 0xcb1ab31fU); }
static inline hf u01(uint32_t h) { return (hf)(h >> 8) * HC(1.0 / 16777216.0); }  // 24 bits: exact in float, never reaches 1

struct RGBf { hf r, g, b; };
static inline RGBf unpack(hf v) {
  uint32_t c = (uint32_t)v;
  return { (hf)((c >> 16) & 255) / HC(255), (hf)((c >> 8) & 255) / HC(255), (hf)(c & 255) / HC(255) };
}

static RGBf hueShift(const RGBf& c, hf deg) {
  hf r = c.r, g = c.g, b = c.b;
  hf mx = maxh(r, maxh(g, b)), mn = minh(r, minh(g, b)), d = mx - mn;
  hf h = 0;
  if (d > 0) {
    if (mx == r) h = fmodp((g - b) / d, 6);
    else if (mx == g) h = (b - r) / d + 2;
    else h = (r - g) / d + 4;
  }
  h = fmodp(h + deg / 60, 6);
  hf s = mx > 0 ? d / mx : HC(0), v = mx;
  int i = (int)std::floor(h);
  hf f = h - i;
  hf p = v * (1 - s), q = v * (1 - s * f), t = v * (1 - s * (1 - f));
  switch (i) {
    case 0:  return { v, t, p };
    case 1:  return { q, v, p };
    case 2:  return { p, v, t };
    case 3:  return { p, q, v };
    case 4:  return { t, p, v };
    default: return { v, p, q };
  }
}

// 2D gradient noise, periodic in x (px) and y (py) so it wraps around a ring and in time
static hf gradNoise(hf x, hf y, int px, int py, uint32_t seed) {
  int ix = (int)std::floor(x), iy = (int)std::floor(y);
  hf fx = x - ix, fy = y - iy;
  int x0 = imodp(ix, px), x1 = imodp(ix + 1, px);
  int y0 = imodp(iy, py), y1 = imodp(iy + 1, py);
  uint32_t g00 = hash3(x0, y0, seed) & 7, g10 = hash3(x1, y0, seed) & 7;
  uint32_t g01 = hash3(x0, y1, seed) & 7, g11 = hash3(x1, y1, seed) & 7;
  hf d00 = GX[g00] * fx + GY[g00] * fy;
  hf d10 = GX[g10] * (fx - 1) + GY[g10] * fy;
  hf d01 = GX[g01] * fx + GY[g01] * (fy - 1);
  hf d11 = GX[g11] * (fx - 1) + GY[g11] * (fy - 1);
  hf u = fx * fx * fx * (fx * (fx * 6 - 15) + 10);
  hf v = fy * fy * fy * (fy * (fy * 6 - 15) + 10);
  hf a = d00 + (d10 - d00) * u, b = d01 + (d11 - d01) * u;
  return a + (b - a) * v;
}

// returns the position (fraction of the width) of the waveform's highest point
static hf buildProfile(int shape, hf width, hf* lut) {
  const Comp* comps = SHAPE_ECG;
  int n = sizeof(SHAPE_ECG) / sizeof(Comp);
  if (shape == 1) { comps = SHAPE_LUBDUB; n = sizeof(SHAPE_LUBDUB) / sizeof(Comp); }
  else if (shape == 2) { comps = SHAPE_BUMP; n = sizeof(SHAPE_BUMP) / sizeof(Comp); }
  hf peak = 0;
  int peakJ = 0;
  for (int j = 0; j < PROFILE_N; j++) {
    hf s = (hf)j / (PROFILE_N - 1);
    hf v = 0;
    for (int c = 0; c < n; c++) {
      hf sl = comps[c].sigma * width;
      hf se = std::sqrt(sl * sl + AA_SIGMA * AA_SIGMA);
      hf z = (s - comps[c].mu) * width / se;
      v += comps[c].amp * sl / se * std::exp(HC(-0.5) * z * z);
    }
    v *= smoothstep(0, HC(0.06), s) * fadeOut(HC(0.94), 1, s);
    lut[j] = v;
    if (v > peak) { peak = v; peakJ = j; }
  }
  if (peak > 0) for (int j = 0; j < PROFILE_N; j++) lut[j] /= peak;
  return (hf)peakJ / (PROFILE_N - 1);
}

static inline hf profileAt(const hf* lut, hf s) {
  if (s <= 0 || s >= 1) return 0;
  hf f = s * (PROFILE_N - 1);
  int i = (int)std::floor(f);
  return lut[i] + (lut[i + 1] - lut[i]) * (f - i);
}

static inline void blendPx(hf* out, int j, hf r, hf g, hf b, hf alpha, uint8_t mode) {
  if (mode == BLEND_ADD) {
    out[j] += r; out[j + 1] += g; out[j + 2] += b;
  } else if (mode == BLEND_SCREEN) {
    out[j]     = 1 - (1 - clamp01(out[j]))     * (1 - clamp01(r));
    out[j + 1] = 1 - (1 - clamp01(out[j + 1])) * (1 - clamp01(g));
    out[j + 2] = 1 - (1 - clamp01(out[j + 2])) * (1 - clamp01(b));
  } else {
    hf ia = 1 - clamp01(alpha);
    out[j] = out[j] * ia + r; out[j + 1] = out[j + 1] * ia + g; out[j + 2] = out[j + 2] * ia + b;
  }
}

static inline uint8_t evGroup(uint8_t type) {
  static const uint8_t groupOf[EV_COUNT] = { GRP_PIECE_IN, GRP_PIECE_OUT, GRP_ALL_IN, GRP_STORY_END };
  return groupOf[type];
}

static hf sanitize(const ParamDef& d, hf v) {
  if (!(v == v)) v = d.d0;  // NaN
  if (v < d.min) v = d.min;
  if (v > d.max) v = d.max;
  if (d.type != PT_FLOAT) v = std::floor(v + HC(0.5));
  return v;
}

// ------------------------------------------------------------------ engine
Engine::Engine() {
  _vals[GRP_GLOBAL] = _global;       _res[GRP_GLOBAL] = _rGlobal;
  _vals[GRP_HEARTBEAT] = _heartbeat; _res[GRP_HEARTBEAT] = _rHeartbeat;
  _vals[GRP_AMBIENT] = _ambient;     _res[GRP_AMBIENT] = _rAmbient;
  _vals[GRP_PIECE_IN] = _pieceIn;    _res[GRP_PIECE_IN] = _rPieceIn;
  _vals[GRP_PIECE_OUT] = _pieceOut;  _res[GRP_PIECE_OUT] = _rPieceOut;
  _vals[GRP_ALL_IN] = _allIn;        _res[GRP_ALL_IN] = _rAllIn;
  _vals[GRP_STORY_END] = _storyEnd;  _res[GRP_STORY_END] = _rStoryEnd;
  _lutPeak = 0;
  _lutShape = -1;
  _lutWidth = -1;
  setDefaults();
  setStripDefaults();
  _numStrips = 1;
  reset();
}

void Engine::setStripDefaults() {
  for (int s = 0; s < MAX_STRIPS; s++) {
    for (int i = 0; i < Sp::COUNT; i++) _strips[s][i] = STRIP_DEFS[i].d0;
    if (s == 1) { _strips[s][Sp::leds] = 100; _strips[s][Sp::yaw] = 90; }  // a second strip defaults to the orthogonal plane
  }
  clearPools();
}

void Engine::setDefaults() {
  for (int g = 0; g < GRP_COUNT; g++) {
    for (int i = 0; i < GROUPS[g].count; i++) _vals[g][i] = { GROUPS[g].defs[i].d0, GROUPS[g].defs[i].d1, GROUPS[g].defs[i].ranged, -1 };
  }
  for (int e = 0; e < MAX_EXPRS; e++) { _exprs[e].used = false; _exprs[e].prog.clear(); _exprs[e].src.clear(); }
  resolve();
}

void Engine::reset() {
  _time = 0;
  _noiseT = 0;
  for (int s = 0; s < MAX_STRIPS; s++) _panOff[s] = 0;
  _level = 0;
  _mask = 0;
  _count = 0;
  _rng = 0x2545F491U;
  _hbPhase = HC(0.9);  // first beat arrives shortly after start
  _extClock = false;
  _pendingBeats = 0;
  _numHbPulses = 0;
  _numTwinkles = 0;
  _numEvents = 0;
  _numSparkles = 0;
  _numAiPulses = 0;
  for (int s = 0; s < MAX_STRIPS; s++) { _twAcc[s] = 0; _spAcc[s] = 0; }
  _puAcc = 0;
  resolve();
}

void Engine::clearPools() {
  _numTwinkles = 0;
  _numSparkles = 0;
  for (int s = 0; s < MAX_STRIPS; s++) { _twAcc[s] = 0; _spAcc[s] = 0; }
}

void Engine::setParam(uint8_t group, uint8_t idx, hf a, hf b, bool ranged) {
  if (group >= GRP_COUNT || idx >= GROUPS[group].count) return;
  const ParamDef& d = GROUPS[group].defs[idx];
  ranged = ranged && (d.type == PT_FLOAT || d.type == PT_INT);
  a = sanitize(d, a);
  b = ranged ? sanitize(d, b) : a;
  freeExpr(group, idx);
  _vals[group][idx] = { a, b, ranged, -1 };
  resolve();
}

void Engine::freeExpr(uint8_t group, uint8_t idx) {
  int8_t e = _vals[group][idx].expr;
  if (e < 0) return;
  _exprs[e].used = false;
  _exprs[e].prog.clear();
  _exprs[e].src.clear();
  _vals[group][idx].expr = -1;
}

bool Engine::setParamExpr(uint8_t group, uint8_t idx, const char* src, char* err, size_t errLen) {
  if (group >= GRP_COUNT || idx >= GROUPS[group].count) return false;
  const ParamDef& d = GROUPS[group].defs[idx];
  if (group == GRP_GLOBAL || (d.type != PT_FLOAT && d.type != PT_INT)) {
    if (err && errLen) snprintf(err, errLen, "%s cannot be an expression", d.key);
    return false;
  }
  ExprProgram prog;
  if (!prog.compile(src, err, errLen)) return false;
  int8_t slot = _vals[group][idx].expr;
  if (slot < 0) {
    for (int e = 0; e < MAX_EXPRS; e++) if (!_exprs[e].used) { slot = e; break; }
    if (slot < 0) { if (err && errLen) snprintf(err, errLen, "too many expressions (max %d)", MAX_EXPRS); return false; }
  }
  _exprs[slot].used = true;
  _exprs[slot].prog = prog;
  _exprs[slot].src = src;
  _vals[group][idx].expr = slot;
  resolve();
  return true;
}

const char* Engine::paramExpr(uint8_t group, uint8_t idx) const {
  int8_t e = _vals[group][idx].expr;
  return e >= 0 ? _exprs[e].src.c_str() : nullptr;
}

void Engine::setStripCount(uint8_t n) {
  if (n < 1) n = 1;
  if (n > MAX_STRIPS) n = MAX_STRIPS;
  if (n != _numStrips) clearPools();
  _numStrips = n;
}

void Engine::setStripParam(uint8_t strip, uint8_t idx, hf v) {
  if (strip >= MAX_STRIPS || idx >= Sp::COUNT) return;  // inactive strips keep their settings too
  v = sanitize(STRIP_DEFS[idx], v);
  if (_strips[strip][idx] == v) return;
  _strips[strip][idx] = v;
  clearPools();
}

uint32_t Engine::randU32() { _rng += 0x9E3779B9U; return hash32(_rng); }
hf Engine::rand01() { return u01(randU32()); }

void Engine::exprVars(hf et, double* vars) const {
  vars[XV_PIECES] = _count;
  vars[XV_T] = _time;
  vars[XV_ET] = et;
  vars[XV_LEVEL] = _level;
  vars[XV_NUMPIECES] = (int)_global[Gp::numPieces].a;
}

// evaluate an expression param and clamp it like any other value (NaN -> default, ints rounded)
hf Engine::evalParam(uint8_t group, uint8_t idx, const double* vars) const {
  const ParamDef& d = GROUPS[group].defs[idx];
  double x = _exprs[_vals[group][idx].expr].prog.eval(vars);
  if (x != x) x = d.d0;
  if (x < d.min) x = d.min;
  if (x > d.max) x = d.max;
  if (d.type != PT_FLOAT) x = std::floor(x + 0.5);
  return (hf)x;
}

void Engine::resolve() {
  hf t = _level;
  double vars[XV_COUNT];
  exprVars(0, vars);
  for (int g = 0; g < GRP_COUNT; g++) {
    for (int i = 0; i < GROUPS[g].count; i++) {
      if (_vals[g][i].expr >= 0) _res[g][i] = evalParam(g, i, vars);
      else _res[g][i] = _vals[g][i].a + (_vals[g][i].b - _vals[g][i].a) * t;
    }
  }
}

// re-evaluate one event group's expressions for a given event age (et)
void Engine::resolveEt(uint8_t group, hf et) {
  double vars[XV_COUNT];
  bool ready = false;
  for (int i = 0; i < GROUPS[group].count; i++) {
    if (_vals[group][i].expr < 0) continue;
    if (!ready) { exprVars(et, vars); ready = true; }
    _res[group][i] = evalParam(group, i, vars);
  }
}

// length of the virtual strip a pattern copy is rendered into
int Engine::vlen(uint8_t si) const {
  int n = iround(_strips[si][Sp::leds] / _strips[si][Sp::reps]);
  return n < 1 ? 1 : n;
}

// Map the virtual pattern onto the physical strip: copy k covers [origin + k*V, origin + (k+1)*V),
// odd copies run backwards when mirrored. The virtual pattern is a ring, so both repeat and
// mirror are seamless at copy boundaries. Fractional positions are linearly interpolated.
void Engine::tile(uint8_t si, int Lv, const hf* v, hf* out) const {
  const hf* st = _strips[si];
  int L = (int)st[Sp::leds];
  int reps = (int)st[Sp::reps];
  hf V = (hf)L / reps;
  for (int i = 0; i < L; i++) {
    hf d0 = fmodp((hf)i - st[Sp::origin], (hf)L);
    int k = (int)std::floor(d0 / V);
    if (k > reps - 1) k = reps - 1;
    hf u = d0 - k * V;
    if (st[Sp::mirror] != 0 && (k & 1)) u = V - u;
    hf x = u * Lv / V;
    int i0 = (int)std::floor(x);
    hf f = x - i0;
    int a = 3 * imodp(i0, Lv), b = 3 * imodp(i0 + 1, Lv), j = 3 * i;
    out[j]     = v[a]     + (v[b]     - v[a])     * f;
    out[j + 1] = v[a + 1] + (v[b + 1] - v[a + 1]) * f;
    out[j + 2] = v[a + 2] + (v[b + 2] - v[a + 2]) * f;
  }
}

hf Engine::reach(hf travel) const {
  hf r = 0;
  for (uint8_t s = 0; s < _numStrips; s++) r = maxh(r, travel * vlen(s));
  return r;
}

hf Engine::cancelEnv(const Event& ev, hf fade) const {
  if (ev.cancelAge < 0) return 1;
  return fade > 0 ? clamp01(1 - (ev.age - ev.cancelAge) / fade) : HC(0);
}

Engine::Timeline Engine::aiTimeline() const {
  const hf* P = _rAllIn;
  Timeline T;
  T.pulseEnd = P[AllIn::pulseStart] + P[AllIn::pulseDuration];
  T.period = 60 / P[AllIn::beatBpm];
  T.holdEnd = T.pulseEnd + P[AllIn::holdDuration];
  T.convStart = maxh(P[AllIn::pulseStart], T.pulseEnd - P[AllIn::convergeDuration]);
  T.end = T.holdEnd + iround(P[AllIn::beatCount]) * T.period;
  return T;
}

hf Engine::eventDuration(const Event& ev) const {
  if (ev.type == EV_ALL_IN) return aiTimeline().end;
  if (ev.type == EV_STORY_END) return _rStoryEnd[StEnd::attack] + _rStoryEnd[StEnd::hold] + _rStoryEnd[StEnd::release];
  if (ev.type == EV_PIECE_IN) return _rPieceIn[PcIn::duration];
  return _rPieceOut[PcOut::duration];
}

EventInfo Engine::eventInfo(uint8_t i) {
  if (i >= _numEvents) return { 0, 0, 0 };
  resolveEt(evGroup(_events[i].type), _events[i].age);
  return { _events[i].type, _events[i].age, eventDuration(_events[i]) };
}

// ------------------------------------------------------------------ inputs
void Engine::setPieces(uint32_t mask, bool events) {
  int np = (int)_global[Gp::numPieces].a;
  mask &= (1U << np) - 1;
  int n = 0;
  for (uint32_t m = mask; m; m &= m - 1) n++;
  int nOld = _count;
  _mask = mask;
  _count = n;
  if (!events || n == nOld || _global[Gp::autoEvents].a == 0) return;
  Event* ai = nullptr;  // a running (not cancelling) last-piece animation
  for (uint8_t e = 0; e < _numEvents; e++) if (_events[e].type == EV_ALL_IN && _events[e].cancelAge < 0) ai = &_events[e];
  bool allInOnCount = _global[Gp::allInTrigger].a == 0;  // otherwise allIn waits for the audio's story start
  if (n >= np && nOld < np && allInOnCount) {
    if (!ai) trigger(EV_ALL_IN);
  } else if (n > nOld) {
    trigger(EV_PIECE_IN);
  } else {
    // near the end of the last-piece animation, letting go is part of the ritual: no reaction
    bool grace = false;
    if (ai) {
      resolveEt(GRP_ALL_IN, ai->age);
      grace = eventDuration(*ai) - ai->age <= _rAllIn[AllIn::releaseGrace];
    }
    if (!grace) {
      trigger(EV_PIECE_OUT);
      if (nOld >= np) cancel(EV_ALL_IN);
    }
  }
}

bool Engine::trigger(uint8_t type) {
  if (type >= EV_COUNT) return false;
  if (_vals[evGroup(type)][0].a == 0) return false;  // param 0 is "enabled" for every event group
  if (type == EV_ALL_IN) {
    uint8_t w = 0;
    for (uint8_t e = 0; e < _numEvents; e++) if (_events[e].type != EV_ALL_IN) _events[w++] = _events[e];
    _numEvents = w;
    _numSparkles = 0;
    _numAiPulses = 0;
    for (int s = 0; s < MAX_STRIPS; s++) _spAcc[s] = 0;
    _puAcc = 0;
  }
  if (_numEvents >= MAX_EVENTS) {
    for (uint8_t e = 1; e < _numEvents; e++) _events[e - 1] = _events[e];
    _numEvents--;
  }
  resolveEt(evGroup(type), 0);
  Event& ev = _events[_numEvents];
  ev.type = type;
  ev.age = 0;
  ev.cancelAge = -1;
  ev.seed = randU32();
  ev.numBursts = 0;
  if (type == EV_PIECE_OUT) {
    const hf* P = _rPieceOut;
    int n = iround(P[PcOut::flickerCount]);
    if (n > MAX_BURSTS) n = MAX_BURSTS;
    hf spanT = maxh(0, P[PcOut::flickerWindow] * P[PcOut::duration] - P[PcOut::flickerLen]);
    for (int b = 0; b < n; b++) {
      hf start = rand01() * spanT;
      hf centre = rand01();
      ev.bursts[b][0] = start;
      ev.bursts[b][1] = centre;
    }
    ev.numBursts = n;
  }
  _numEvents++;
  return true;
}

void Engine::cancel(uint8_t type) {
  for (uint8_t e = 0; e < _numEvents; e++) {
    Event& ev = _events[e];
    if (ev.type != type || ev.cancelAge >= 0) continue;
    resolveEt(evGroup(type), ev.age);
    if (type == EV_ALL_IN && _rAllIn[AllIn::cancelFade] <= 0) continue;
    ev.cancelAge = ev.age;
  }
}

void Engine::setExternalClock(bool on) {
  if (on == _extClock) return;
  _extClock = on;
  _pendingBeats = 0;
  if (!on) _hbPhase = 0;  // the internal clock resumes a full period after the last external beat
}

void Engine::beat() {
  if (_pendingBeats < 4) _pendingBeats++;
}

void Engine::clearEvents() {
  _numEvents = 0;
  _numSparkles = 0;
  _numAiPulses = 0;
}

// ------------------------------------------------------------------ time & output
void Engine::tick(hf dt) {
  if (!(dt > 0)) return;
  _time += dt;
  int np = (int)_global[Gp::numPieces].a;
  hf tau = _global[Gp::levelSmoothing].a;
  hf target = np > 1 ? (hf)(_count < np - 1 ? _count : np - 1) / (np - 1) : HC(1);
  _level = tau > 0 ? _level + (target - _level) * (1 - std::exp(-dt / tau)) : target;
  resolve();
  tickHeartbeat(dt);
  tickAmbient(dt);
  tickEvents(dt);
}

void Engine::render(uint8_t si, hf* out) {
  if (si >= _numStrips) return;
  int Lv = vlen(si);
  if ((int)_scratch.size() < 3 * Lv) { _scratch.resize(3 * Lv); _vbuf.resize(3 * Lv); }
  hf* v = _vbuf.data();
  for (int j = 0; j < 3 * Lv; j++) v[j] = 0;
  renderHeartbeat(si, v);
  renderAmbient(si, v);
  for (uint8_t e = 0; e < _numEvents; e++) {
    const Event& ev = _events[e];
    resolveEt(evGroup(ev.type), ev.age);
    if (ev.type == EV_PIECE_IN) renderPieceIn(ev, si, v);
    else if (ev.type == EV_PIECE_OUT) renderPieceOut(ev, si, v);
    else if (ev.type == EV_ALL_IN) renderAllIn(ev, si, v);
    else if (ev.type == EV_STORY_END) renderStoryEnd(ev, si, v);
  }
  for (int j = 0; j < 3 * Lv; j++) v[j] = clamp01(v[j]);
  tile(si, Lv, v, out);
}

// ------------------------------------------------------------------ heartbeat
void Engine::tickHeartbeat(hf dt) {
  const hf* H = _rHeartbeat;
  if (H[Hb::enabled] == 0) { _numHbPulses = 0; _pendingBeats = 0; return; }
  int shape = (int)H[Hb::shape];
  if (shape != _lutShape || H[Hb::pulseWidth] != _lutWidth) {
    _lutPeak = buildProfile(shape, H[Hb::pulseWidth], _lut);
    _lutShape = shape;
    _lutWidth = H[Hb::pulseWidth];
  }
  hf period = 60 / H[Hb::bpm];
  for (int p = 0; p < _numHbPulses; p++) _hbPulses[p] += H[Hb::pulseSpeed] * dt;
  if (_extClock) {
    // externally clocked: the waveform's peak (the lub) is at the origin the moment the beat arrives
    for (; _pendingBeats > 0; _pendingBeats--) pushPulse(_lutPeak * H[Hb::pulseWidth]);
  } else {
    _hbPhase += dt / period;
    while (_hbPhase >= 1) {
      _hbPhase -= 1;
      pushPulse(_hbPhase * period * H[Hb::pulseSpeed]);
    }
  }
  hf limit = reach(H[Hb::travel]) + H[Hb::pulseWidth];
  int w = 0;
  for (int p = 0; p < _numHbPulses; p++) if (_hbPulses[p] <= limit) _hbPulses[w++] = _hbPulses[p];
  _numHbPulses = w;
}

void Engine::pushPulse(hf x) {
  if (_numHbPulses >= MAX_HB_PULSES) {
    for (int p = 1; p < _numHbPulses; p++) _hbPulses[p - 1] = _hbPulses[p];
    _numHbPulses--;
  }
  _hbPulses[_numHbPulses++] = x;
}

hf Engine::hbSum(hf d, hf xmax, hf taper) const {
  const hf* H = _rHeartbeat;
  hf s = 0;
  hf W = H[Hb::pulseWidth];
  for (int p = 0; p < _numHbPulses; p++) {
    hf sp = (_hbPulses[p] - d) / W;
    if (sp <= 0 || sp >= 1) continue;
    s += profileAt(_lut, sp);
  }
  if (s == 0) return 0;
  return s * (1 - H[Hb::fade] * d / xmax) * fadeOut(xmax - taper, xmax, d);
}

void Engine::renderHeartbeat(uint8_t si, hf* out) {
  const hf* H = _rHeartbeat;
  if (H[Hb::enabled] == 0) return;
  int L = vlen(si);
  hf V = (hf)L;
  hf xmax = H[Hb::travel] * V;
  hf taper = minh(H[Hb::pulseWidth], xmax * HC(0.25));
  RGBf col = unpack(H[Hb::color]);
  hf op = H[Hb::opacity];
  uint8_t mode = (uint8_t)H[Hb::blend];
  int dir = (int)H[Hb::direction];
  for (int i = 0; i < L; i++) {
    hf u = (hf)i;  // virtual pixel = distance from the origin
    hf v = H[Hb::brightness];
    if (dir != DIR_BWD && u <= xmax) v += H[Hb::pulseAmp] * hbSum(u, xmax, taper);
    if (dir != DIR_FWD && V - u <= xmax) v += H[Hb::pulseAmp] * hbSum(V - u, xmax, taper);
    hf c = clamp01(v);
    hf wh = H[Hb::peakWhite] * clamp01(v - 1);
    blendPx(out, 3 * i,
      (col.r * c + (1 - col.r) * wh) * op,
      (col.g * c + (1 - col.g) * wh) * op,
      (col.b * c + (1 - col.b) * wh) * op, op, mode);
  }
}

// ------------------------------------------------------------------ ambient
void Engine::tickAmbient(hf dt) {
  const hf* A = _rAmbient;
  _noiseT += A[Am::noiseSpeed] * dt;
  if (_noiseT >= NOISE_TP) _noiseT -= NOISE_TP;
  for (uint8_t s = 0; s < _numStrips; s++) _panOff[s] = fmodp(_panOff[s] + A[Am::noisePan] * dt, (hf)vlen(s));
  int w = 0;
  for (int t = 0; t < _numTwinkles; t++) {
    _twinkles[t].age += dt;
    if (_twinkles[t].age < _twinkles[t].life) _twinkles[w++] = _twinkles[t];
  }
  _numTwinkles = w;
  if (A[Am::enabled] == 0) return;
  RGBf col = unpack(A[Am::twinkleColor]);
  for (uint8_t s = 0; s < _numStrips; s++) {
    hf Lv = (hf)vlen(s);
    _twAcc[s] += A[Am::twinkleRate] * Lv / 100 * dt;
    while (_twAcc[s] >= 1) {
      _twAcc[s] -= 1;
      if (_numTwinkles >= MAX_TWINKLES) continue;
      Twinkle& tw = _twinkles[_numTwinkles++];
      // separate statements: PRNG draw order must match engine.js
      tw.strip = s;
      tw.pos = rand01() * Lv;
      tw.life = A[Am::twinkleLife] * (HC(0.75) + HC(0.5) * rand01());
      tw.phase = rand01();
      hf hue = (rand01() * 2 - 1) * A[Am::twinkleHueVar];
      RGBf rgb = hueShift(col, hue);
      tw.r = rgb.r; tw.g = rgb.g; tw.b = rgb.b;
      tw.bright = HC(0.6) + HC(0.4) * rand01();
      tw.age = 0;
    }
  }
}

void Engine::renderAmbient(uint8_t si, hf* out) {
  const hf* A = _rAmbient;
  if (A[Am::enabled] == 0) return;
  int L = vlen(si);
  hf* sc = _scratch.data();
  RGBf nc = unpack(A[Am::noiseColor]);
  int period = iround((hf)L / A[Am::noiseScale]);
  if (period < 1) period = 1;
  int oct = iround(A[Am::noiseOctaves]);
  if (oct > 4) oct = 4;
  if (oct < 1) oct = 1;
  hf ty = _noiseT + si * HC(17.31);
  for (int i = 0; i < L; i++) {
    hf x = ((hf)i - _panOff[si]) * period / L;
    hf n = 0, norm = 0, amp = 1;
    int f = 1;
    for (int o = 0; o < oct; o++) {
      n += amp * gradNoise(x * f, ty * f + o * HC(13.7), period * f, NOISE_TP * f, o + 1);
      norm += amp; amp *= HC(0.5); f *= 2;
    }
    hf nv = clamp01(HC(0.5) + HC(1.2) * n / norm);
    hf k = A[Am::noiseAmount] * smoothstep(A[Am::noiseThreshold], 1, nv);
    sc[3 * i] = nc.r * k; sc[3 * i + 1] = nc.g * k; sc[3 * i + 2] = nc.b * k;
  }
  hf size = A[Am::twinkleSize];
  for (int t = 0; t < _numTwinkles; t++) {
    const Twinkle& tw = _twinkles[t];
    if (tw.strip != si) continue;
    hf tau = tw.age / tw.life;
    hf env = smoothstep(0, HC(0.25), tau) * fadeOut(HC(0.55), 1, tau);
    hf osc = 1 - A[Am::shimmer] * HC(0.5) * (1 + std::sin(TWO_PI_H * (A[Am::shimmerHz] * tw.age + tw.phase)));
    hf val = A[Am::twinkleBrightness] * tw.bright * env * osc;
    if (val <= 0) continue;
    int i0 = (int)std::ceil(tw.pos - size), i1 = (int)std::floor(tw.pos + size);
    for (int i = i0; i <= i1; i++) {
      hf dd = std::fabs((hf)i - tw.pos);
      if (dd >= size) continue;
      hf wgt = val * HC(0.5) * (1 + std::cos(PI_H * dd / size));
      int j = 3 * imodp(i, L);
      sc[j] += tw.r * wgt; sc[j + 1] += tw.g * wgt; sc[j + 2] += tw.b * wgt;
    }
  }
  hf op = A[Am::opacity];
  uint8_t mode = (uint8_t)A[Am::blend];
  for (int i = 0; i < L; i++) {
    int j = 3 * i;
    hf r = sc[j] * op, g = sc[j + 1] * op, b = sc[j + 2] * op;
    blendPx(out, j, r, g, b, minh(1, maxh(r, maxh(g, b))), mode);
  }
}

// ------------------------------------------------------------------ events
void Engine::tickEvents(hf dt) {
  uint8_t w = 0;
  for (uint8_t e = 0; e < _numEvents; e++) {
    Event& ev = _events[e];
    ev.age += dt;
    resolveEt(evGroup(ev.type), ev.age);
    if (ev.type == EV_ALL_IN) tickAllIn(ev, dt);
    bool done = ev.age >= eventDuration(ev);
    if (ev.cancelAge >= 0) {
      hf fade = ev.type == EV_ALL_IN ? _rAllIn[AllIn::cancelFade] : HC(0);
      if (ev.age - ev.cancelAge >= fade) done = true;
    }
    if (!done) _events[w++] = ev;
  }
  _numEvents = w;
}

void Engine::renderPieceIn(const Event& ev, uint8_t si, hf* out) {
  const hf* P = _rPieceIn;
  int L = vlen(si);
  hf V = (hf)L;
  hf xmax = P[PcIn::travel] * V;
  hf taper = minh(P[PcIn::width], xmax * HC(0.25));
  int n = iround(P[PcIn::numPulses]);
  int dir = (int)P[PcIn::direction];
  uint8_t mode = (uint8_t)P[PcIn::blend];
  hf dur = P[PcIn::duration];
  hf env = fadeOut(dur - minh(HC(0.4), dur * HC(0.3)), dur, ev.age);
  hf gain = P[PcIn::intensity] * P[PcIn::opacity] * env;
  RGBf col = unpack(P[PcIn::color]);
  for (int i = 0; i < L; i++) {
    hf u = (hf)i;  // virtual pixel = distance from the origin
    hf sum = 0;
    for (int pass = 0; pass < 2; pass++) {
      if (pass == 0 && dir == DIR_BWD) continue;
      if (pass == 1 && dir == DIR_FWD) continue;
      hf d = pass == 0 ? u : V - u;
      if (d > xmax) continue;
      hf atten = (1 - P[PcIn::travelFade] * d / xmax) * fadeOut(xmax - taper, xmax, d);
      hf mag = 1;
      for (int p = 0; p < n; p++) {
        hf tp = p * P[PcIn::interval];
        if (ev.age < tp) break;
        hf s = ((ev.age - tp) * P[PcIn::speed] - d) / P[PcIn::width];
        hf c = 0;
        if (s > HC(-0.15) && s < 0) c = (s + HC(0.15)) / HC(0.15);
        else if (s >= 0 && s < 1) c = (1 - s) * (1 - s);
        sum += mag * c * atten;
        mag *= P[PcIn::decay];
      }
    }
    if (sum <= 0) continue;
    hf k = sum * gain;
    hf r = col.r * k, g = col.g * k, b = col.b * k;
    blendPx(out, 3 * i, r, g, b, minh(1, maxh(r, maxh(g, b))), mode);
  }
}

void Engine::renderPieceOut(const Event& ev, uint8_t si, hf* out) {
  const hf* P = _rPieceOut;
  int L = vlen(si);
  hf dur = P[PcOut::duration];
  hf envA = P[PcOut::dimAttack] > 0 ? clamp01(ev.age / P[PcOut::dimAttack]) : HC(1);
  hf envR = P[PcOut::dimRelease] > 0 ? clamp01((dur - ev.age) / P[PcOut::dimRelease]) : (ev.age < dur ? HC(1) : HC(0));
  hf dim = P[PcOut::dimAmount] * envA * envR * P[PcOut::opacity];
  hf hw = P[PcOut::flickerArea] * L * HC(0.5);
  for (int i = 0; i < L; i++) {
    hf f = 1 - dim;
    for (int b = 0; b < ev.numBursts; b++) {
      hf bt = ev.age - ev.bursts[b][0];
      if (bt < 0 || bt >= P[PcOut::flickerLen]) continue;
      hf dd = std::fabs(fmodp((hf)i - ev.bursts[b][1] * L + L * HC(0.5), (hf)L) - L * HC(0.5));
      if (dd >= hw) continue;
      hf wgt = HC(0.5) * (1 + std::cos(PI_H * dd / hw));
      uint32_t step = (uint32_t)(int)std::floor(bt * P[PcOut::flickerRate]);
      hf fv = P[PcOut::flickerLow] + (P[PcOut::flickerHigh] - P[PcOut::flickerLow]) * u01(hash3(ev.seed, b, step));
      f *= 1 + (fv - 1) * wgt * P[PcOut::opacity];
    }
    int j = 3 * i;
    out[j] *= f; out[j + 1] *= f; out[j + 2] *= f;
  }
}

void Engine::tickAllIn(Event& ev, hf dt) {
  const hf* P = _rAllIn;
  Timeline T = aiTimeline();
  int w = 0;
  for (int k = 0; k < _numSparkles; k++) {
    _sparkles[k].age += dt;
    if (_sparkles[k].age < _sparkles[k].life) _sparkles[w++] = _sparkles[k];
  }
  _numSparkles = w;
  w = 0;
  for (int k = 0; k < _numAiPulses; k++) {
    _aiPulses[k].age += dt;
    if (_aiPulses[k].age < _aiPulses[k].life) _aiPulses[w++] = _aiPulses[k];
  }
  _numAiPulses = w;

  if (ev.cancelAge >= 0) return;  // no new spawns while cancelling
  if (ev.age < P[AllIn::sparkleDuration]) {
    for (uint8_t s = 0; s < _numStrips; s++) {
      hf Lv = (hf)vlen(s);
      _spAcc[s] += P[AllIn::sparkleDensity] * Lv / 100 * dt;
      while (_spAcc[s] >= 1) {
        _spAcc[s] -= 1;
        if (_numSparkles >= MAX_SPARKLES) continue;
        Sparkle& sp = _sparkles[_numSparkles++];
        sp.strip = s;
        sp.pos = (int)std::floor(rand01() * Lv);
        sp.life = P[AllIn::sparkleLife] * (HC(0.6) + HC(0.8) * rand01());
        sp.bright = HC(0.5) + HC(0.5) * rand01();
        sp.age = 0;
      }
    }
  }
  if (ev.age >= P[AllIn::pulseStart] && ev.age < T.pulseEnd) {
    hf prog = (ev.age - P[AllIn::pulseStart]) / P[AllIn::pulseDuration];
    _puAcc += (P[AllIn::pulseRateStart] + (P[AllIn::pulseRateEnd] - P[AllIn::pulseRateStart]) * prog * prog) * dt;
    while (_puAcc >= 1) {
      _puAcc -= 1;
      if (_numAiPulses >= MAX_AI_PULSES) continue;
      AiPulse& pu = _aiPulses[_numAiPulses++];
      pu.phi = rand01();
      pu.dir = rand01() < HC(0.5) ? -1 : 1;
      pu.width = P[AllIn::pulseWidthMin] + (P[AllIn::pulseWidthMax] - P[AllIn::pulseWidthMin]) * rand01();
      pu.speed = P[AllIn::pulseSpeedMin] + (P[AllIn::pulseSpeedMax] - P[AllIn::pulseSpeedMin]) * rand01();
      pu.life = P[AllIn::pulseLife] * (HC(0.7) + HC(0.6) * rand01());
      pu.bright = HC(0.6) + HC(0.4) * rand01();
      pu.age = 0;
    }
  }
}

void Engine::renderAllIn(const Event& ev, uint8_t si, hf* out) {
  const hf* P = _rAllIn;
  Timeline T = aiTimeline();
  int L = vlen(si);
  hf* sc = _scratch.data();
  hf age = ev.age;
  hf op = P[AllIn::opacity] * cancelEnv(ev, P[AllIn::cancelFade]);
  if (op <= 0) return;
  RGBf col = unpack(P[AllIn::color]), spc = unpack(P[AllIn::sparkleColor]);

  // solid colour: converge -> hold -> decaying release beats
  hf conv = smoothstep(T.convStart, T.pulseEnd, age);
  hf occ, solid;
  if (age < T.holdEnd) {
    occ = conv;
    hf r = u01(hash3(ev.seed, 7, (uint32_t)(int)std::floor(age * 18)));
    solid = conv * (1 - P[AllIn::convergeFlicker] * 4 * conv * (1 - conv) * r);
  } else {
    hf tb = age - T.holdEnd;
    hf n = std::floor(tb / T.period);
    hf ph = tb - n * T.period;
    hf presence = clamp01(1 - tb / (T.end - T.holdEnd));
    hf lub = std::exp(-P[AllIn::beatDecay] * ph);
    hf dub = ph >= P[AllIn::dubDelay] ? P[AllIn::dubStrength] * std::exp(-P[AllIn::beatDecay] * (ph - P[AllIn::dubDelay])) : HC(0);
    occ = presence;
    solid = presence * (P[AllIn::beatFloor] + (1 - P[AllIn::beatFloor]) * maxh(lub, dub));
  }
  for (int i = 0; i < L; i++) {
    sc[3 * i] = col.r * solid; sc[3 * i + 1] = col.g * solid; sc[3 * i + 2] = col.b * solid;
  }

  // sparkles: single pixels, sharp rise and fall
  hf spEnv = smoothstep(0, HC(0.5), age) * fadeOut(minh(P[AllIn::pulseStart], P[AllIn::sparkleDuration]), P[AllIn::sparkleDuration], age);
  for (int k = 0; k < _numSparkles; k++) {
    const Sparkle& sp = _sparkles[k];
    if (sp.strip != si || sp.pos >= L) continue;
    hf tau = sp.age / sp.life;
    hf shape = tau < HC(0.15) ? tau / HC(0.15) : (1 - (tau - HC(0.15)) / HC(0.85)) * (1 - (tau - HC(0.15)) / HC(0.85));
    hf v = P[AllIn::sparkleBrightness] * sp.bright * spEnv * shape;
    int j = 3 * sp.pos;
    sc[j] += spc.r * v; sc[j + 1] += spc.g * v; sc[j + 2] += spc.b * v;
  }

  // crossing pulses, fading into the solid as it converges
  hf puGain = P[AllIn::pulseBrightness] * (1 - conv);
  if (puGain > 0) {
    for (int k = 0; k < _numAiPulses; k++) {
      const AiPulse& pu = _aiPulses[k];
      hf env = std::sin(PI_H * pu.age / pu.life);
      hf v = puGain * pu.bright * env;
      hf hw = pu.width * HC(0.5);
      hf pos = fmodp(pu.phi * L + pu.dir * pu.speed * pu.age, (hf)L);
      int i0 = (int)std::ceil(pos - hw), i1 = (int)std::floor(pos + hw);
      for (int i = i0; i <= i1; i++) {
        hf dd = std::fabs((hf)i - pos);
        if (dd >= hw) continue;
        hf wgt = v * HC(0.5) * (1 + std::cos(PI_H * dd / hw));
        int j = 3 * imodp(i, L);
        sc[j] += col.r * wgt; sc[j + 1] += col.g * wgt; sc[j + 2] += col.b * wgt;
      }
    }
  }

  hf ia = 1 - occ * op;
  for (int j = 0; j < 3 * L; j++) out[j] = out[j] * ia + sc[j] * op;
}

// ------------------------------------------------------------------ story end
// A warm glow spreading from the origin and fading: the "exhale" after a story.
void Engine::renderStoryEnd(const Event& ev, uint8_t si, hf* out) {
  const hf* P = _rStoryEnd;
  int L = vlen(si);
  hf V = (hf)L;
  hf a = P[StEnd::attack], h = P[StEnd::hold];
  hf env = (a > 0 ? smoothstep(0, a, ev.age) : HC(1)) * fadeOut(a + h, a + h + P[StEnd::release], ev.age);
  hf gain = P[StEnd::intensity] * P[StEnd::opacity] * env;
  if (gain <= 0) return;
  hf front = P[StEnd::speed] * ev.age;
  hf soft = P[StEnd::softness];
  hf xmax = P[StEnd::travel] * V;
  hf taper = minh(soft, xmax * HC(0.25));
  RGBf col = unpack(P[StEnd::color]);
  uint8_t mode = (uint8_t)P[StEnd::blend];
  for (int i = 0; i < L; i++) {
    hf d = minh((hf)i, V - i);
    if (d > xmax) continue;
    hf k = gain * smoothstep(d, d + soft, front) * fadeOut(xmax - taper, xmax, d);
    if (k <= 0) continue;
    hf r = col.r * k, g = col.g * k, b = col.b * k;
    blendPx(out, 3 * i, r, g, b, minh(1, maxh(r, maxh(g, b))), mode);
  }
}

